// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// Captura os dados combinados vindos do nó Merge
const input = $json;

// Garante o acesso aos clientes (do Webhook) e aos investimentos (do Code anterior)
const clientes = input.clientes || input.body?.clientes || [];
const investimentos = input.investimentos || [];

// Função auxiliar para converter "R$ 12.500,00" para o número 12500
function parseSaldo(saldoStr) {
  if (typeof saldoStr === 'number') return saldoStr;
  if (!saldoStr) return 0;
  return Number(String(saldoStr).replace(/[^\d]/g, '')) || 0;
}

// Função auxiliar para escolher um item aleatório de uma lista
function pick(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

const resultados = clientes.map(c => {
  const saldoNum = parseSaldo(c.saldo);
  const perfil = c.perfil;
  const nome = c.nome;

  // Encontra o investimento compatível com o perfil do cliente
  const escolhido = investimentos.find(
    inv => String(inv.perfil).toLowerCase() === String(perfil).toLowerCase()
  ) || null;

  let motivo = "saldo_ok";
  if (escolhido && saldoNum < escolhido.minimo) {
    motivo = "saldo_insuficiente";
  }

  // Gera as 3 variações de mensagens vistas no output do professor
  const mensagens = escolhido ? [
    `Olá ${nome}! Pelo seu perfil (${perfil}), uma boa opção é **${escolhido.produto}** (mínimo R$ ${escolhido.minimo}). Com seu saldo atual (${c.saldo}), você já consegue investir. Rentabilidade: ${escolhido.rentabilidade || escolhido.taxa || 'N/A'}.`,
    `Oi ${nome}! Recomendação para perfil ${perfil}: **${escolhido.produto}** (mínimo R$ ${escolhido.minimo}). Seu saldo (${c.saldo}) já atende o mínimo. Rentabilidade: ${escolhido.rentabilidade || escolhido.taxa || 'N/A'}.`,
    `${nome}, indo direto ao ponto: para o perfil ${perfil}, **${escolhido.produto}** (mínimo R$ ${escolhido.minimo}). Você tem ${c.saldo}, então dá pra aplicar. Rentabilidade: ${escolhido.rentabilidade || escolhido.taxa || 'N/A'}.`
  ] : [
    `Olá ${nome}, não encontramos um produto específico para o perfil ${perfil}.`
  ];

  return {
    nome,
    email: c.email,
    perfil,
    saldo_texto: c.saldo,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens)
  };
});

// Retorna no mesmo formato da linha 112-118 do print
return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];
